const crypto = require('crypto');

const GDPR_SECRET = $env.PERSONA_GDPR_SECRET || 'change-me-in-production';
const PUBLIC_URL = ($env.PERSONA_PUBLIC_URL || 'http://localhost:5678').replace(/\/$/, '');
const OLLAMA_HOST = $env.OLLAMA_HOST || 'http://host-gateway:11434';
const OLLAMA_MODEL = $env.OLLAMA_MODEL || 'llama3.2';
const GEMINI_KEY = $env.GEMINI_API_KEY || '';

function signGdprToken(userId, action) {
  const exp = Date.now() + 72 * 3600000;
  const payload = Buffer.from(JSON.stringify({ userId, action, exp })).toString('base64url');
  const sig = crypto.createHmac('sha256', GDPR_SECRET).update(payload).digest('base64url');
  return `${payload}.${sig}`;
}

function gdprLink(userId, action) {
  const token = signGdprToken(userId, action);
  return `${PUBLIC_URL}/webhook/persona-gdpr?token=${encodeURIComponent(token)}&action=${action}`;
}

function parseRssItems(xml, sourceName) {
  const items = [];
  const chunks = String(xml).split('<item>');
  for (let i = 1; i < chunks.length && items.length < 15; i++) {
    const block = chunks[i].split('</item>')[0];
    const title = (block.match(/<title><!\[CDATA\[(.*?)\]\]><\/title>/) || block.match(/<title>(.*?)<\/title>/))?.[1] || '';
    const link = (block.match(/<link>(.*?)<\/link>/) || [])[1] || '';
    const desc = (block.match(/<description><!\[CDATA\[(.*?)\]\]><\/description>/) || block.match(/<description>(.*?)<\/description>/))?.[1] || '';
    if (title) {
      items.push({
        title: title.trim(),
        url: link.trim(),
        description: desc.replace(/<[^>]+>/g, '').trim().slice(0, 300),
        source: sourceName
      });
    }
  }
  return items;
}

const trigger = $('When Executed by Another Workflow').first().json;
const rows = $('Get All Users').all().map(i => i.json);
let user = null;
if (trigger.userId) {
  user = rows.find(r => r.username === trigger.userId || String(r.id) === String(trigger.userId));
}
if (!user && trigger.sessionToken) {
  user = rows.find(r => r.session_token === trigger.sessionToken);
}
if (!user) {
  return [{ json: { success: false, error: 'Utilisateur introuvable.' } }];
}
if (user.active === false) {
  return [{ json: { success: false, error: 'Newsletter desactivee pour ce compte.' } }];
}

const RSS_FEEDS = [
  { url: 'https://feeds.bbci.co.uk/news/technology/rss.xml', name: 'BBC Technology' },
  { url: 'https://feeds.arstechnica.com/arstechnica/technology-lab', name: 'Ars Technica' },
  { url: 'https://www.france24.com/fr/rss', name: 'France 24' }
];

let allArticles = [];
for (const feed of RSS_FEEDS) {
  try {
    const xml = await this.helpers.httpRequest({ method: 'GET', url: feed.url, timeout: 15000 });
    allArticles = allArticles.concat(parseRssItems(xml, feed.name));
  } catch (e) { /* feed indisponible */ }
}

const blockedSources = (user.blocked_sources || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const blockedTopics = (user.blocked_topics || '').toLowerCase().split(',').map(s => s.trim()).filter(Boolean);
const interests = user.interests || '';

const seen = new Set();
allArticles = allArticles.filter(a => {
  const key = a.title.toLowerCase().slice(0, 60);
  if (seen.has(key)) return false;
  seen.add(key);
  if (blockedSources.some(s => a.source.toLowerCase().includes(s))) return false;
  if (blockedTopics.some(t => a.title.toLowerCase().includes(t) || a.description.toLowerCase().includes(t))) return false;
  return true;
}).slice(0, 20);

if (allArticles.length === 0) {
  return [{ json: { success: false, error: 'Aucun article disponible pour le moment.' } }];
}

const articlesText = allArticles.map((a, i) =>
  `[${i + 1}] ${a.title} | ${a.description} | ${a.url} | ${a.source}`
).join('\n');

const style = user.newsletter_style || 'standard';
const maxArticles = style === 'brief' ? 3 : style === 'deep' ? 8 : 5;
const prefs = user.preferences || '';

const prompt = `Tu es Persona, curateur de news personnalisees.
Utilisateur: ${user.username}
Centres d'interet: ${interests}
Preferences: ${prefs || 'aucune'}
Style: ${style} (max ${maxArticles} articles)

Articles disponibles:
${articlesText}

Selectionne les ${maxArticles} articles les plus pertinents pour cet utilisateur.
Pour CHAQUE article retenu, explique en 1 phrase pourquoi il correspond (champ "pertinence").

Reponds UNIQUEMENT en JSON valide sans markdown:
{"articles":[{"titre":"...","resume":"2-3 phrases en francais","url":"...","source":"...","pertinence":"..."}]}`;

let aiText = '';
try {
  if (GEMINI_KEY) {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key=${GEMINI_KEY}`,
      headers: { 'Content-Type': 'application/json' },
      body: { contents: [{ parts: [{ text: prompt }] }] },
      json: true,
      timeout: 60000
    });
    aiText = res.candidates?.[0]?.content?.parts?.[0]?.text || '';
  } else {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: `${OLLAMA_HOST}/api/generate`,
      body: { model: OLLAMA_MODEL, prompt, stream: false },
      json: true,
      timeout: 120000
    });
    aiText = res.response || '';
  }
} catch (e) {
  return [{ json: { success: false, error: 'IA indisponible. Verifiez Ollama ou GEMINI_API_KEY.' } }];
}

let data;
try {
  const clean = aiText.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(clean);
} catch (e) {
  data = {
    articles: [{
      titre: 'Actualites du jour',
      resume: aiText.slice(0, 500),
      url: '#',
      source: 'Persona AI',
      pertinence: 'Selection automatique'
    }]
  };
}

const articles = (data.articles || []).slice(0, maxArticles);
const uid = String(user.username || user.id);

let articlesHtml = '';
articles.forEach((a, i) => {
  const pert = a.pertinence || 'Correspond a vos centres d interet.';
  articlesHtml += `
    <div style="margin-bottom:24px;padding:20px;border-left:4px solid #E8420A;background:#f9f9f9;border-radius:0 8px 8px 0;">
      <h3 style="color:#1A3A6B;margin:0 0 8px 0;font-size:18px;">${i + 1}. ${a.titre}</h3>
      <p style="color:#444;line-height:1.6;margin:0 0 10px 0;">${a.resume}</p>
      <p style="color:#888;font-size:12px;margin:0 0 8px 0;background:#eef;padding:8px;border-radius:4px;">
        <strong>Pourquoi cette actu ?</strong> ${pert}
      </p>
      <p style="color:#666;font-size:13px;margin:0 0 8px 0;"><strong>Source :</strong> ${a.source}</p>
      <a href="${a.url}" style="color:#E8420A;font-weight:bold;text-decoration:none;">Lire l article complet</a>
    </div>`;
});

const unsubLink = gdprLink(uid, 'unsubscribe');
const exportLink = gdprLink(uid, 'export');
const deleteLink = gdprLink(uid, 'delete');

const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"></head>
<body style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;background:#f5f5f5;">
  <div style="background:linear-gradient(135deg,#1A3A6B,#2E5FA3);padding:32px;text-align:center;border-radius:12px 12px 0 0;">
    <h1 style="color:white;margin:0;font-size:26px;">Persona</h1>
    <p style="color:#FFD6A5;margin:10px 0 0 0;">Bonjour ${user.username} - votre briefing personnalise</p>
  </div>
  <div style="padding:24px;background:white;">
    <p style="color:#666;font-size:14px;">Centres d interet : <strong>${interests}</strong></p>
    <hr style="border:none;border-top:1px solid #eee;margin:16px 0;">
    ${articlesHtml}
    <div style="margin-top:24px;padding:16px;background:#f0f7ff;border-radius:8px;border:1px dashed #1A3A6B;">
      <p style="margin:0 0 8px 0;font-size:14px;color:#1A3A6B;"><strong>Donnez votre avis</strong></p>
      <p style="margin:0;font-size:13px;color:#555;">Repondez a cet email : "Je n ai pas aime l article 2" ou "Plus de sport, moins de crypto"</p>
    </div>
  </div>
  <div style="background:#2a2a2a;padding:20px;border-radius:0 0 12px 12px;text-align:center;">
    <p style="color:#aaa;font-size:12px;margin:0 0 12px 0;">RGPD - vos droits en un clic (liens signes, valides 72h)</p>
    <a href="${unsubLink}" style="color:#FFD6A5;margin:0 8px;font-size:12px;">Se desinscrire</a>
    <a href="${exportLink}" style="color:#FFD6A5;margin:0 8px;font-size:12px;">Exporter mes donnees</a>
    <a href="${deleteLink}" style="color:#ff6b6b;margin:0 8px;font-size:12px;">Supprimer mon compte</a>
    <p style="color:#666;font-size:11px;margin:16px 0 0 0;">Persona - Newsletter IA sans interface</p>
  </div>
</body></html>`;

return [{
  json: {
    success: true,
    html,
    email: user.email,
    username: user.username,
    userId: uid,
    subject: `Persona - Votre briefing du ${new Date().toLocaleDateString('fr-FR')}`,
    articleCount: articles.length,
    source: trigger.source || 'preview'
  }
}];
